## 'Today in ETH': one card per day with the most interesting number of the last day.
## Numbers are never generated by the LLM: code computes candidate facts from our data, the LLM only picks one and writes the text.

GEMINI_MODEL = 'gemini-3.8-flash'
GEMINI_TEMPERATURE = 0.4
CARDS_IN_JSON = 30          ## cards served in daily.json -> data.today (newest first)
RECENT_CARDS_FOR_PROMPT = 14  ## the LLM sees these to avoid repeating topics
SPARKLINE_DAYS = 30
MIN_RECORD_DAYS = 60        ## 'highest/lowest since' only counts if the previous higher/lower value is at least this old
## we prefer positive ETH developments: score multiplier by sentiment of the candidate's notable move (a big negative story can still win)
SENTIMENT_SCORE_FACTOR = {'positive': 1.5, 'neutral': 1.0, 'negative': 0.6}

## metric definitions: unit + how to format, and the source credited on the card
CARD_METRICS = {
    ## good: +1 = up is good for ETH, -1 = down is good, 0 = neutral
    'eth_price':          {'name': 'ETH price', 'unit': 'usd', 'good': 1, 'sources': ['coingecko']},
    'net_supply_annual':  {'name': 'Net ETH supply change (30d, annualized)', 'unit': 'percent_signed', 'good': -1, 'sources': ['ethsupply', 'growthepie']},
    'staked_share':       {'name': 'Share of ETH supply staked', 'unit': 'percent', 'good': 1, 'sources': ['ethsupply', 'growthepie', 'ultrasound']},
    'staking_yield':      {'name': 'Staking yield (7d avg)', 'unit': 'percent', 'good': 0, 'sources': ['ethsupply', 'growthepie']},
    'eth_burned':         {'name': 'ETH burned per day', 'unit': 'eth', 'good': 1, 'sources': ['growthepie']},
    'gas_paid_eth':       {'name': 'ETH paid as gas per day (Ethereum + L2s)', 'unit': 'eth', 'good': 1, 'sources': ['growthepie']},
    'l2_median_tx_cost':  {'name': 'Median L2 transaction cost', 'unit': 'usd_small', 'good': -1, 'sources': ['growthepie']},
    'txcount_total':      {'name': 'Transactions per day (Ethereum + L2s)', 'unit': 'count', 'good': 1, 'sources': ['growthepie']},
    'eth_btc_ratio':      {'name': 'ETH/BTC market cap ratio', 'unit': 'ratio', 'good': 1, 'sources': ['coingecko', 'yahoo', 'blockchain_com']},
    ## slow-moving levels: progress here is often gradual, so records in the good direction count even without an unusual move
    'eth_staked':         {'name': 'ETH staked', 'unit': 'eth_millions', 'good': 1, 'level': True, 'sources': ['ethsupply', 'growthepie']},
    'l2_median_tx_cost_30d': {'name': 'Median L2 transaction cost (30d avg)', 'unit': 'usd_small', 'good': -1, 'level': True, 'sources': ['growthepie']},
    'txcount_total_30d':  {'name': 'Transactions per day (Ethereum + L2s, 30d avg)', 'unit': 'count', 'good': 1, 'level': True, 'sources': ['growthepie']},
    ## Ethereum mainnet
    'stables_mcap':       {'name': 'Stablecoin supply on Ethereum', 'unit': 'usd_big', 'good': 1, 'level': True, 'sources': ['growthepie']},
    'gas_per_second':     {'name': 'Ethereum throughput (gas per second)', 'unit': 'gas_rate', 'good': 1, 'sources': ['growthepie']},
    'gas_limit':          {'name': 'Ethereum gas limit per block', 'unit': 'gas', 'good': 1, 'level': True, 'event': True, 'sources': ['growthepie']},  ## only news when it changed in the last 7 days
    'mainnet_txcount':    {'name': 'Transactions per day on Ethereum mainnet', 'unit': 'count', 'good': 1, 'sources': ['growthepie']},
    'mainnet_tx_cost':    {'name': 'Median transaction cost on Ethereum mainnet', 'unit': 'usd_small', 'good': -1, 'sources': ['growthepie']},
    'mainnet_daa':        {'name': 'Daily active addresses on Ethereum mainnet', 'unit': 'count', 'good': 1, 'sources': ['growthepie']},
    'mainnet_aa_30d':     {'name': 'Active addresses on Ethereum mainnet (last 30 days)', 'unit': 'count', 'good': 1, 'level': True, 'sources': ['growthepie']},
    'app_fees_usd':       {'name': 'Fees earned by apps on Ethereum mainnet per day', 'unit': 'usd_big', 'good': 1, 'sources': ['growthepie']},
    'active_apps':        {'name': 'Apps active per day on Ethereum mainnet', 'unit': 'count', 'good': 1, 'sources': ['growthepie']},
    'stablecoin_tx_share': {'name': 'Share of Ethereum mainnet transactions that move stablecoins (7d)', 'unit': 'percent', 'good': 1, 'level': True, 'sources': ['growthepie']},
}


def fmt_value(v:float, unit:str):
    if unit == 'usd':
        return f'${v:,.2f}' if abs(v) < 1000 else f'${v:,.0f}'
    if unit == 'usd_small':
        return f'${v:.4f}' if v < 0.01 else f'${v:.3f}'
    if unit == 'percent_signed':
        return f'{v*100:+.2f}%'
    if unit == 'percent':
        return f'{v*100:.2f}%' if v < 0.1 else f'{v*100:.1f}%'
    if unit == 'eth':
        return f'{v:,.0f} ETH' if v >= 10 else f'{v:,.2f} ETH'
    if unit == 'usd_big':
        return f'${v/1e9:,.1f}B' if v >= 1e9 else (f'${v/1e6:,.1f}M' if v >= 1e6 else f'${v:,.0f}')
    if unit == 'gas_rate':
        return f'{v/1e6:,.2f} Mgas/s'
    if unit == 'gas':
        return f'{v/1e6:,.0f}M gas'
    if unit == 'eth_millions':
        return f'{v/1e6:,.2f}M ETH'
    if unit == 'count':
        return f'{v/1e6:,.1f}M' if v >= 1e6 else f'{v:,.0f}'
    if unit == 'ratio':
        return f'{v:.4f}'
    return f'{v:,.2f}'


class EthTodayCards():
    def __init__(self, s3_bucket, cf_distribution_id, db_connector, api_version='v1'):
        self.s3_bucket = s3_bucket
        self.cf_distribution_id = cf_distribution_id
        self.db_connector = db_connector
        self.api_version = api_version
        self.asset = EthAssetJSONCreation(s3_bucket, cf_distribution_id, db_connector, api_version)

    ## ----------------- Daily metric series (complete days) --------------------

    def get_metric_series(self):
        from src.main_config import get_main_config
        db = self.db_connector
        today = pd.Timestamp(datetime.now(timezone.utc).date())
        series = {}

        eim = db.execute_query("""
            SELECT "date", metric_key, value FROM public.eim_fact
            WHERE origin_key = 'ethereum' AND "date" >= '2022-09-15'
                AND metric_key IN ('eth_supply_eth', 'eth_burned_eth', 'eth_staked_eth', 'staking_rewards_cl_eth', 'staking_yield_cl', 'staking_yield_el')
        """, load_df=True)
        eim['date'] = pd.to_datetime(eim['date'])
        e = eim.pivot_table(index='date', columns='metric_key', values='value', aggfunc='last').sort_index()
        e = e[e.index < today]

        series['eth_burned'] = e['eth_burned_eth']
        series['eth_staked'] = e['eth_staked_eth']
        series['staked_share'] = e['eth_staked_eth'] / e['eth_supply_eth']
        series['staking_yield'] = (e['staking_yield_cl'] + e['staking_yield_el']).rolling(7).mean()
        ## since the Merge: issuance = net CL rewards, so supply change = issuance - burn
        flows = (e['staking_rewards_cl_eth'] - e['eth_burned_eth']).rolling(30).sum()
        series['net_supply_annual'] = flows * 365 / 30 / e['eth_supply_eth']

        price = db.execute_query("""
            SELECT "date", value FROM public.fact_kpis WHERE origin_key = 'ethereum' AND metric_key = 'price_usd' AND "date" >= '2021-01-01'
        """, load_df=True)
        series['eth_price'] = pd.Series(price['value'].values, index=pd.to_datetime(price['date'])).sort_index()
        series['eth_price'] = series['eth_price'][series['eth_price'].index < today]

        ## chains with ETH as gas token (same scope as the 'ETH paid as gas' card), L2s = all of them except Ethereum
        chains = [c.origin_key for c in get_main_config() if c.metadata_gas_token == 'ETH' and c.api_in_main and c.api_deployment_flag == 'PROD']
        ok_string = "', '".join(chains)
        k = db.execute_query(f"""
            SELECT "date", origin_key, metric_key, value FROM public.fact_kpis
            WHERE origin_key IN ('{ok_string}') AND metric_key IN ('fees_paid_eth', 'txcount', 'txcosts_median_usd') AND "date" >= '2022-01-01'
        """, load_df=True)
        k['date'] = pd.to_datetime(k['date'])
        k = k[k['date'] < today]
        series['gas_paid_eth'] = k[k['metric_key'] == 'fees_paid_eth'].groupby('date')['value'].sum()
        series['txcount_total'] = k[k['metric_key'] == 'txcount'].groupby('date')['value'].sum()

        ## median L2 tx cost: txcount-weighted median of the chains' daily median tx cost
        l2 = k[k['origin_key'] != 'ethereum'].pivot_table(index=['date', 'origin_key'], columns='metric_key', values='value').dropna(subset=['txcount', 'txcosts_median_usd'])
        def weighted_median(g):
            g = g.sort_values('txcosts_median_usd')
            cum = g['txcount'].cumsum()
            return g['txcosts_median_usd'][cum >= g['txcount'].sum() / 2].iloc[0]
        series['l2_median_tx_cost'] = l2.groupby(level='date').apply(weighted_median)
        series['l2_median_tx_cost_30d'] = series['l2_median_tx_cost'].rolling(30).mean()
        series['txcount_total_30d'] = series['txcount_total'].rolling(30).mean()

        ## Ethereum mainnet metrics from fact_kpis
        mainnet_keys = {'stables_mcap': 'stables_mcap', 'gas_per_second': 'gas_per_second', 'gas_limit': 'gas_limit', 'txcount': 'mainnet_txcount',
                        'txcosts_median_usd': 'mainnet_tx_cost', 'daa': 'mainnet_daa', 'aa_last30d': 'mainnet_aa_30d', 'app_fees_usd': 'app_fees_usd'}
        mk_string = "', '".join(mainnet_keys)
        m = db.execute_query(f"""
            SELECT "date", metric_key, value FROM public.fact_kpis
            WHERE origin_key = 'ethereum' AND metric_key IN ('{mk_string}') AND "date" >= '2015-08-07'
        """, load_df=True)
        m['date'] = pd.to_datetime(m['date'])
        m = m[m['date'] < today].pivot_table(index='date', columns='metric_key', values='value', aggfunc='last')
        for mk, key in mainnet_keys.items():
            if mk in m.columns:
                series[key] = m[mk]

        ## active apps: distinct projects with activity per day
        apps = db.execute_query("""
            SELECT "date", COUNT(DISTINCT owner_project) AS value FROM public.vw_apps_contract_level_materialized
            WHERE origin_key = 'ethereum' AND "date" >= current_date - interval '800 days' AND "date" < current_date
            GROUP BY 1
        """, load_df=True)
        series['active_apps'] = pd.Series(apps['value'].values, index=pd.to_datetime(apps['date']))

        ## stablecoin share of mainnet transactions (7d rolling)
        bs = db.execute_query("""
            SELECT "date", category_id, txcount FROM public.blockspace_fact_category_level
            WHERE origin_key = 'ethereum' AND category_id IN ('stablecoin', 'total_usage') AND "date" >= current_date - interval '800 days' AND "date" < current_date
        """, load_df=True)
        bs['date'] = pd.to_datetime(bs['date'])
        bs = bs.pivot_table(index='date', columns='category_id', values='txcount', aggfunc='sum').sort_index()
        series['stablecoin_tx_share'] = bs['stablecoin'].rolling(7).sum() / bs['total_usage'].rolling(7).sum()

        ## lifetime totals for milestones (not scored like the other metrics)
        lt = db.execute_query("""
            SELECT "date", metric_key, value FROM public.fact_kpis
            WHERE origin_key = 'ethereum' AND metric_key IN ('lifetime_txcount', 'lifetime_fees_paid_eth') AND "date" < current_date
        """, load_df=True)
        lt['date'] = pd.to_datetime(lt['date'])
        self.lifetime = {k_: g.set_index('date')['value'].sort_index() for k_, g in lt.groupby('metric_key')}

        ratio = self.asset.get_eth_btc_ratio([{'key': 'eth', 'market_cap_usd': 1}, {'key': 'btc', 'market_cap_usd': 1}])
        series['eth_btc_ratio'] = pd.Series({pd.Timestamp(t, unit='ms'): v for t, v in ratio['data']})

        return {k_: s.dropna().sort_index() for k_, s in series.items()}

    ## ----------------- Candidate facts --------------------

    ## facts for one metric on its latest day: changes, records ('highest since'), unusualness of the 7d move
    def build_candidate(self, key:str, s:pd.Series):
        cfg = CARD_METRICS[key]
        if len(s) < 60:
            return None
        ## event metrics (e.g. gas limit) are only candidates if they changed in the last 7 days
        if cfg.get('event'):
            week = s[s.index >= s.index[-1] - pd.Timedelta(days=7)]
            if (week.max() - week.min()) / week.min() < 0.01:
                return None
        date, value = s.index[-1], float(s.iloc[-1])
        hdate = lambda d: d.strftime('%b %-d, %Y')  ## human readable dates, the LLM has to reuse them as given
        facts = {'value': fmt_value(value, cfg['unit']), 'date': hdate(date)}

        for days in [1, 7, 30]:
            prev = s[s.index <= date - pd.Timedelta(days=days)]
            if len(prev) > 0 and prev.iloc[-1] != 0:
                if cfg['unit'].startswith('percent'):
                    diff = (value - prev.iloc[-1]) * 100
                    if abs(diff) >= 0.005:
                        facts[f'change_{days}d'] = f'{diff:+.2f} percentage points'
                else:
                    facts[f'change_{days}d'] = f'{(value / prev.iloc[-1] - 1)*100:+.1f}%'

        ## record: last date with a higher (for highs) or lower (for lows) value
        hist = s.iloc[:-1]
        record_days, record_type = 0, None
        higher, lower = hist[hist >= value], hist[hist <= value]
        if len(higher) == 0:
            record_type, record_days = f'highest since at least {hdate(hist.index[0])} (when our records for this metric start)', (date - hist.index[0]).days
        elif (date - higher.index[-1]).days >= MIN_RECORD_DAYS:
            record_type, record_days = f'highest since {hdate(higher.index[-1])}', (date - higher.index[-1]).days
        if len(lower) == 0:
            record_type, record_days = f'lowest since at least {hdate(hist.index[0])} (when our records for this metric start)', (date - hist.index[0]).days
        elif (date - lower.index[-1]).days >= MIN_RECORD_DAYS and (date - lower.index[-1]).days > record_days:
            record_type, record_days = f'lowest since {hdate(lower.index[-1])}', (date - lower.index[-1]).days
        if record_type:
            facts['record'] = record_type

        ## unusualness: z-scores of the latest 7d and 30d change vs. the same changes over the last year
        def change_z(days):
            chg = s.diff(days) if cfg['unit'].startswith('percent') else s.pct_change(days)
            chg = chg.replace([np.inf, -np.inf], np.nan).dropna()
            ly = chg[chg.index >= date - pd.Timedelta(days=365)]
            return float((ly.iloc[-1] - ly.mean()) / ly.std()) if len(ly) > 30 and ly.std() > 0 else 0.0
        z7, z30 = change_z(7), change_z(30)
        move = min(max(abs(z7), abs(z30) * 0.8), 4.0)
        ## for unusual moves, give the typical 7d change over the last year as context (e.g. a stalled trend)
        if abs(z7) >= 2:
            chg = s.diff(7) if cfg['unit'].startswith('percent') else s.pct_change(7)
            typical = chg[chg.index >= date - pd.Timedelta(days=365)].replace([np.inf, -np.inf], np.nan).dropna().mean()
            facts['typical_7d_change_last_year'] = f'{typical*100:+.2f} percentage points' if cfg['unit'].startswith('percent') else f'{typical*100:+.1f}%'
            if 'change_7d' not in facts:
                facts['change_7d'] = '+0.00 percentage points' if cfg['unit'].startswith('percent') else '+0.0%'
        ## a record only counts if the move behind it is unusual too, in the same direction (slow trends set 'records' all the time)
        if record_type and record_type.startswith('highest'):
            record_move = max(z7, z30 * 0.8, 0)
        elif record_type:
            record_move = max(-z7, -z30 * 0.8, 0)
        else:
            record_move = 0
        if cfg.get('level') and record_type and cfg['good'] == (1 if record_type.startswith('highest') else -1):
            record_move = max(record_move, 0.5)
        record_bonus = np.log1p(record_days / 30) * 1.5 * min(1.0, record_move)
        score = move + record_bonus
        z = z7

        ## sentiment: direction of the notable part (record if it counts, else the bigger of the 7d/30d moves) vs. the metric's good direction
        if record_bonus > 0:
            direction = 1 if record_type.startswith('highest') else -1
        else:
            dz = z7 if abs(z7) >= abs(z30) * 0.8 else z30
            direction = int(np.sign(dz))
        good = cfg['good']
        prev30 = s[s.index <= date - pd.Timedelta(days=30)]
        good_direction_30d = bool(good != 0 and len(prev30) > 0 and np.sign(value - prev30.iloc[-1]) == good)
        ## percentage metrics: tiny absolute drifts (< 0.05 percentage points in 30d) are not news, even if statistically unusual
        if cfg['unit'].startswith('percent') and len(prev30) > 0 and abs(value - prev30.iloc[-1]) * 100 < 0.05:
            good_direction_30d = False
        notable = move >= 1.0 or record_bonus > 0
        sentiment = 'neutral' if good == 0 or direction == 0 or not notable else ('positive' if direction == good else 'negative')
        score = score * SENTIMENT_SCORE_FACTOR[sentiment]
        spark = s[s.index > date - pd.Timedelta(days=SPARKLINE_DAYS)]
        unix = (spark.index - pd.Timestamp('1970-01-01')) // pd.Timedelta(milliseconds=1)
        return {
            'candidate_id': key,
            'metric': cfg['name'],
            'unit': cfg['unit'],
            'value': value,
            'facts': facts,
            'zscore_7d_change': round(z, 2),
            'sentiment': sentiment,
            'good_direction_30d': good_direction_30d,
            'zscore_30d_change': round(z30, 2),
            'score': round(float(score), 2),
            'sparkline': [[int(u), float(v)] for u, v in zip(unix, spark.values)],
            'sources': [SOURCES[s_] for s_ in CARD_METRICS[key]['sources']],
        }

    ## lifetime totals on Ethereum mainnet: candidate when a round number was crossed on the latest day
    def get_lifetime_milestones(self, as_of=None):
        cfgs = {
            'lifetime_txcount': {'id': 'lifetime_tx_milestone', 'metric': 'Total transactions ever on Ethereum mainnet', 'step': 100e6, 'big': 500e6,
                                 'fmt': lambda v: f'{v/1e9:,.2f}B', 'unit': 'count'},
            'lifetime_fees_paid_eth': {'id': 'lifetime_fees_milestone', 'metric': 'Total fees ever paid on Ethereum mainnet', 'step': 10e3, 'big': 100e3,
                                       'fmt': lambda v: f'{v/1e6:,.2f}M ETH', 'unit': 'eth'},
        }
        out = []
        for key, cfg in cfgs.items():
            s = getattr(self, 'lifetime', {}).get(key)
            if s is None:
                continue
            if as_of is not None:
                s = s[s.index <= pd.Timestamp(as_of)]
            if len(s) < 2:
                continue
            now, prev = float(s.iloc[-1]), float(s.iloc[-2])
            if now // cfg['step'] == prev // cfg['step']:
                continue
            milestone = (now // cfg['step']) * cfg['step']
            out.append({
                'candidate_id': cfg['id'], 'metric': cfg['metric'], 'unit': cfg['unit'], 'value': now,
                'facts': {'value': cfg['fmt'](now), 'milestone_crossed': cfg['fmt'](milestone), 'date': s.index[-1].strftime('%b %-d, %Y')},
                'zscore_7d_change': 0.0, 'zscore_30d_change': 0.0, 'sentiment': 'positive', 'good_direction_30d': True,
                'score': round((2.5 if milestone % cfg['big'] == 0 else 1.2) * SENTIMENT_SCORE_FACTOR['positive'], 2),
                'sparkline': [], 'sources': [SOURCES['growthepie']],
            })
        return out

    ## total wallets (lifetime unique addresses that sent a tx on Ethereum): candidate when a round number was crossed yesterday
    def get_wallets_milestone(self, as_of=None):
        from src.misc.jinja_helper import execute_jinja_query
        today = pd.Timestamp(datetime.now(timezone.utc).date())
        end = pd.Timestamp(as_of) + pd.Timedelta(days=1) if as_of is not None else today
        days_back = (today - end).days
        q = lambda d: int(execute_jinja_query(self.db_connector, 'api/select_total_aa.sql.j2', {'origin_key': 'ethereum', 'days': d}, return_df=True).iloc[0]['value'])
        now, prev = q(days_back), q(days_back + 1)
        step = 1_000_000
        if now // step == prev // step:
            return None
        milestone = (now // step) * step
        big = milestone % 10_000_000 == 0 or milestone % 5_000_000 == 0
        return {
            'candidate_id': 'total_wallets_milestone',
            'metric': 'Total Ethereum wallets (unique addresses that ever sent a transaction)',
            'unit': 'count', 'value': float(now),
            'facts': {'value': f'{now/1e6:,.1f}M', 'milestone_crossed': f'{milestone/1e6:,.0f}M wallets', 'date': (end - pd.Timedelta(days=1)).strftime('%b %-d, %Y')},
            'zscore_7d_change': 0.0, 'zscore_30d_change': 0.0, 'sentiment': 'positive',
            'score': round((2.5 if big else 1.2) * SENTIMENT_SCORE_FACTOR['positive'], 2),
            'sparkline': [], 'sources': [SOURCES['growthepie']],
        }

    ## total wallets growth over the last 7 days: always positive, the last-resort candidate for positive-only cards
    def get_wallets_growth(self, as_of=None):
        from src.misc.jinja_helper import execute_jinja_query
        today = pd.Timestamp(datetime.now(timezone.utc).date())
        end = pd.Timestamp(as_of) + pd.Timedelta(days=1) if as_of is not None else today
        days_back = (today - end).days
        q = lambda d: int(execute_jinja_query(self.db_connector, 'api/select_total_aa.sql.j2', {'origin_key': 'ethereum', 'days': d}, return_df=True).iloc[0]['value'])
        now, week_ago = q(days_back), q(days_back + 7)
        return {
            'candidate_id': 'total_wallets_growth',
            'metric': 'New Ethereum wallets (unique addresses sending their first transaction)',
            'unit': 'count', 'value': float(now - week_ago),
            'facts': {'value': f'{(now - week_ago)/1e6:,.2f}M new wallets in 7 days', 'total_wallets': f'{now/1e6:,.1f}M', 'date': (end - pd.Timedelta(days=1)).strftime('%b %-d, %Y')},
            'zscore_7d_change': 0.0, 'sentiment': 'mild_positive', 'good_direction_30d': True,
            'score': 0.3, 'sparkline': [], 'sources': [SOURCES['growthepie']],
        }

    ## positive-only pool, metrics used in the last 7 cards are skipped. Order of preference:
    ##   1. notable positive candidates  2. mild positives (30d trend in the good direction with a modest move) + wallet growth  3. repeats
    def select_positive(self, candidates:list, as_of=None, recent_ids:list=None):
        recent = set((recent_ids or [])[:7])
        positive = [c for c in candidates if c['sentiment'] == 'positive']
        fresh_positive = [c for c in positive if c['candidate_id'] not in recent]
        if fresh_positive:
            return fresh_positive

        ## mild positives need at least a modest 30d move in the good direction (tiny drifts are not news)
        mild = [dict(c, sentiment='mild_positive') for c in candidates
                if c.get('good_direction_30d') and c['sentiment'] != 'negative' and abs(c.get('zscore_30d_change', 0)) >= 0.3]
        try:
            mild.append(self.get_wallets_growth(as_of))
        except Exception as e:
            print(f"...wallets growth failed: {e}")
        fresh_mild = sorted([c for c in mild if c['candidate_id'] not in recent], key=lambda c: -c['score'])
        if fresh_mild:
            return fresh_mild
        return positive or sorted(mild, key=lambda c: -c['score'])

    ## as_of: only use data up to (incl.) this date, for backtests / simulations
    def get_candidates(self, series:dict=None, as_of=None):
        series = series if series is not None else self.get_metric_series()
        if as_of is not None:
            series = {k: v[v.index <= pd.Timestamp(as_of)] for k, v in series.items()}
        candidates = [c for c in (self.build_candidate(k, s) for k, s in series.items()) if c]
        try:
            wallets = self.get_wallets_milestone(as_of)
            if wallets:
                candidates.append(wallets)
        except Exception as e:
            print(f"...wallets milestone failed: {e}")
        candidates += self.get_lifetime_milestones(as_of)
        return sorted(candidates, key=lambda c: -c['score'])

    ## ----------------- LLM --------------------

    def build_prompt(self, candidates:list, recent_cards:list):
        cands = [{'candidate_id': c['candidate_id'], 'metric': c['metric'], **c['facts'], 'sentiment_for_eth': c['sentiment'], 'unusualness_score': c['score']} for c in candidates]
        recent = [{'date': r['date'], 'candidate_id': r['candidate_id'], 'headline': r['headline']} for r in recent_cards]
        return f"""You write the daily "Today in ETH" card for growthepie, an Ethereum analytics site. The card shows one number with a short headline and one sentence.

Pick the single most interesting candidate for a general crypto audience. Prefer records ("highest since ..."), unusual moves (high unusualness_score) and clear stories. Avoid a metric that was used in the last 7 days unless something truly notable happened.

This card only highlights positive developments for ETH (growing usage, more ETH staked, more ETH burned, cheaper transactions, ETH gaining on BTC, supply getting scarcer).
All candidates below are positive or mildly positive. Frame the card constructively, but stay truthful: only mention the facts that support the positive point,
never present a negative fact as positive and never imply causes or benefits that are not in the facts. You may leave out facts that are not positive.

Rules:
- Use only the facts given for the chosen candidate. Do not add numbers, dates, causes or predictions that are not in the facts.
- headline: max 45 characters, plain language, no exclamation marks, no emojis.
- sentence: max 160 characters, explains what the number means for ETH. Write numbers and dates exactly as given in the facts, or none at all.
  Time windows like "7 days" or "30 days" are fine. Don't mention internal terms like "unusualness score", "candidate" or "our data".
- Don't repeat the date of the value itself (the card already shows it); dates of earlier records ("lowest since ...") are fine.
- Neutral, factual tone. No financial advice, no hype.

Recent cards (newest first):
{json.dumps(recent, indent=1)}

Candidates (pre-sorted by unusualness):
{json.dumps(cands, indent=1)}
"""

    def ask_llm(self, prompt:str):
        import os
        from google import genai
        from google.genai import types as genai_types
        client = genai.Client(api_key=os.getenv('GEMINI_API_KEY'))
        schema = genai_types.Schema(
            type=genai_types.Type.OBJECT,
            properties={
                'reasoning': genai_types.Schema(type=genai_types.Type.STRING, description='Why this candidate is the most interesting today (1-2 sentences).'),
                'candidate_id': genai_types.Schema(type=genai_types.Type.STRING),
                'headline': genai_types.Schema(type=genai_types.Type.STRING),
                'sentence': genai_types.Schema(type=genai_types.Type.STRING),
            },
            required=['reasoning', 'candidate_id', 'headline', 'sentence'],
            property_ordering=['reasoning', 'candidate_id', 'headline', 'sentence'],
        )
        response = client.models.generate_content(
            model=GEMINI_MODEL, contents=prompt,
            config=genai_types.GenerateContentConfig(temperature=GEMINI_TEMPERATURE, response_mime_type='application/json', response_schema=schema),
        )
        return json.loads(response.text)

    ## the LLM output is only accepted if it picks a known candidate, respects lengths and uses no numbers outside the candidate's facts
    def validate(self, out:dict, candidates:dict):
        c = candidates.get(out.get('candidate_id'))
        if c is None:
            return False, 'unknown candidate'
        headline, sentence = out.get('headline', '').strip(), out.get('sentence', '').strip()
        if not headline or not sentence or len(headline) > 60 or len(sentence) > 200:
            return False, 'length'
        ## numbers glued to letters (e.g. 'L2s') are ignored; standard time windows are always allowed
        number_re = r'(?<![A-Za-z])\d+(?:[.,]\d+)*'
        allowed = ' '.join(str(v) for v in c['facts'].values()) + ' ' + c['metric']
        allowed_numbers = set(re.findall(number_re, allowed)) | {'1', '7', '24', '30', '365'}
        used_numbers = set(re.findall(number_re, re.sub(r'Layer[ -]2', 'Layer two', headline + ' ' + sentence)))
        if not used_numbers <= allowed_numbers:
            return False, f'numbers not in facts: {used_numbers - allowed_numbers}'
        return True, 'ok'

    ## deterministic fallback if the LLM fails or is rejected
    def fallback_text(self, c:dict):
        f = c['facts']
        headline = f"{c['metric']}: {f['value']}"
        if 'record' in f:
            sentence = f"{c['metric']} is at {f['value']}, the {f['record']}."
        elif 'change_7d' in f:
            sentence = f"{c['metric']} is at {f['value']} ({f['change_7d']} over 7 days)."
        else:
            sentence = f"{c['metric']} is at {f['value']}."
        return headline[:60], sentence[:200]

    ## ----------------- Cards --------------------

    def get_recent_cards(self, limit:int):
        df = self.db_connector.execute_query(f"""
            SELECT card_date, candidate_id, headline, sentence, value_formatted, payload
            FROM public.eth_today_cards ORDER BY card_date DESC LIMIT {limit}
        """, load_df=True)
        return [{'date': str(r['card_date']), 'candidate_id': r['candidate_id'], 'headline': r['headline'], 'payload': r['payload']} for _, r in df.iterrows()]

    ## card_date: the day the card is published, it uses data up to the day before (as_of). series can be passed for backfills.
    def create_card(self, dry_run:bool=False, card_date=None, series:dict=None):
        card_date = pd.Timestamp(card_date) if card_date is not None else pd.Timestamp(datetime.now(timezone.utc).date())
        as_of = card_date - pd.Timedelta(days=1)
        recent = [r for r in self.get_recent_cards(RECENT_CARDS_FOR_PROMPT + 10) if r['date'] < str(card_date.date())][:RECENT_CARDS_FOR_PROMPT] if not dry_run else []
        candidates = self.select_positive(self.get_candidates(series=series, as_of=as_of), as_of=as_of, recent_ids=[r['candidate_id'] for r in recent])
        by_id = {c['candidate_id']: c for c in candidates}

        model, reasoning = GEMINI_MODEL, None
        try:
            out = self.ask_llm(self.build_prompt(candidates, recent))
            ok, why = self.validate(out, by_id)
        except Exception as e:
            out, ok, why = {}, False, f'llm error: {e}'
        if ok:
            chosen, headline, sentence, reasoning = by_id[out['candidate_id']], out['headline'].strip(), out['sentence'].strip(), out.get('reasoning')
        else:
            print(f"...LLM output rejected ({why}), using fallback")
            used_recently = {r['candidate_id'] for r in recent[:7]}
            chosen = next((c for c in candidates if c['candidate_id'] not in used_recently), candidates[0])
            headline, sentence = self.fallback_text(chosen)
            model = 'fallback'

        card = {
            'date': card_date.strftime('%Y-%m-%d'),
            'data_date': chosen['facts']['date'],
            'candidate_id': chosen['candidate_id'],
            'metric': chosen['metric'],
            'value': chosen['value'],
            'value_formatted': chosen['facts']['value'],
            'unit': chosen['unit'],
            'headline': headline,
            'sentence': sentence,
            'sparkline': {'types': ['unix', 'value'], 'data': chosen['sparkline']},
            'sources': chosen['sources'],
            'model': model,
        }
        return card, reasoning, candidates

    def insert_card(self, card:dict, reasoning:str):
        from sqlalchemy import text
        with self.db_connector.engine.begin() as conn:
            conn.execute(text("""
                INSERT INTO public.eth_today_cards (card_date, candidate_id, headline, sentence, value_formatted, model, reasoning, payload)
                VALUES (:card_date, :candidate_id, :headline, :sentence, :value_formatted, :model, :reasoning, CAST(:payload AS jsonb))
                ON CONFLICT (card_date) DO NOTHING
            """), {'card_date': card['date'], 'candidate_id': card['candidate_id'], 'headline': card['headline'], 'sentence': card['sentence'],
                   'value_formatted': card['value_formatted'], 'model': card['model'], 'reasoning': reasoning, 'payload': json.dumps(card)})

    def create_today_json(self):
        cards = [r['payload'] if isinstance(r['payload'], dict) else json.loads(r['payload']) for r in self.get_recent_cards(CARDS_IN_JSON)]
        details_dict = {
            'data': {'cards': cards},
            'last_updated_utc': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
        }
        details_dict = fix_dict_nan(details_dict, 'eth_asset/today')
        write_local_section(self.s3_bucket, self.api_version, 'today', details_dict)
        print('DONE -- ETH today cards json export done')
        return details_dict

    def notify_discord(self, card:dict):
        import os
        from src.misc.helper_functions import send_discord_message
        webhook = os.getenv('GTP_AI_WEBHOOK_URL')
        if not webhook:
            print("...GTP_AI_WEBHOOK_URL not set, skipping notification")
            return
        msg = (f"**Today in ETH ({card['date']})**\n**{card['value_formatted']}** {card['metric']}\n"
               f"**{card['headline']}**\n{card['sentence']}\n_model: {card['model']}_ · https://api.growthepie.com/{self.api_version}/eth_asset/daily.json")
        send_discord_message(msg, webhook_url=webhook)

    ## daily entry point: create today's card (once per day), store it, publish the json, notify
    def run_daily(self):
        today = datetime.now(timezone.utc).strftime('%Y-%m-%d')
        if any(r['date'] == today for r in self.get_recent_cards(1)):
            print(f"Card for {today} already exists, only refreshing the json.")
            return self.create_today_json()
        card, reasoning, _ = self.create_card()
        self.insert_card(card, reasoning)
        details = self.create_today_json()
        self.notify_discord(card)
        return details
